    fn derive_struct() {
        #[derive(Store)]
        struct TodoItem {
            checked: bool,
            contents: String,
        }

        #[store]
        impl Store<TodoItem> {
            fn is_checked(&self) -> bool {
                self.checked().cloned()
            }

            fn check(&mut self) {
                self.checked().set(true);
            }
        }

