            let subscriptions = StoreSubscriptions::new();

            // Track how many times each reactive context is marked dirty.
            let root_hits = Arc::new(AtomicUsize::new(0));
            let child_hits = Arc::new(AtomicUsize::new(0));
            let leaf_hits = Arc::new(AtomicUsize::new(0));

            let make_rc = |hits: Arc<AtomicUsize>| {
                ReactiveContext::new_with_callback(
                    move || {
