            // shallow subscriber at a great-grandchild path.
            subscriptions.deep_subscribers(&[]).add(root);
            subscriptions.deep_subscribers(&[1, 2]).add(child);
            subscriptions.shallow_subscribers(&[1, 2, 3]).add(leaf);

