            // deep subscribers.
            subscriptions.mark_dirty(&[1]);

            // The root deep subscriber is an ancestor of `[1]` -> notified once.
            assert_eq!(root_hits.load(Ordering::SeqCst), 1);
            // The `[1, 2]` deep subscriber is a descendant of `[1]` -> notified once.
            assert_eq!(child_hits.load(Ordering::SeqCst), 1);
            // The `[1, 2, 3]` shallow subscriber is a descendant of `[1]` -> notified once.
            assert_eq!(leaf_hits.load(Ordering::SeqCst), 1);
        });
    }
