211	    /// Subscribe to a specific path in the store. Only writes to this exact path will notify the
212	    /// current reactive context.
213	    pub(crate) fn track(&self, key: &[PathKey]) {
214	        if let Some(rc) = ReactiveContext::current() {
215	            rc.subscribe(self.shallow_subscribers(key));
216	        }
217	    }
