219	    /// Subscribe to a path and all of its descendants. This should be called any time we give out
220	    /// a raw reference to a store, because the user could read any level of the store. Writes to this
221	    /// path or any path below it will notify the current reactive context.
222	    pub(crate) fn track_deep(&self, key: &[PathKey]) {
223	        if let Some(rc) = ReactiveContext::current() {
224	            rc.subscribe(self.deep_subscribers(key));
225	        }
226	    }
227	
228	    /// Mark the node and all of its descendants as dirty. This also notifies any deep subscribers on
229	    /// ancestor paths, so that components that read a whole parent value re-render when a nested child
230	    /// field is written to.
231	    pub(crate) fn mark_dirty(&self, key: &[PathKey]) {
232	        // Notify every subscriber (shallow and deep) at this path and all of its descendants.
233	        let paths = {
234	            let read = &self.inner.read_unchecked();
235	            match read.root.get(key) {
236	                Some(node) => {
237	                    let mut paths = Vec::new();
238	                    node.paths_under(key, &mut paths);
239	                    paths
240	                }
241	                // Even if this node was never subscribed to, ancestor deep subscribers still need to
242	                // be notified about the change below them.
243	                None => Vec::new(),
244	            }
245	        };
246	        for path in paths {
247	            self.notify(&path, SubscriptionDepth::Shallow);
248	            self.notify(&path, SubscriptionDepth::Deep);
249	        }
250	        // Notify deep subscribers on every ancestor of this path.
251	        self.mark_ancestors_dirty(key);
252	    }
