254	    /// Mark exactly this node as dirty (not its descendants) while still notifying deep subscribers on
255	    /// ancestor paths. This is used for changes that only affect the value at this path along with any
256	    /// parent that observes the whole value, like pushing to a `Vec` (which changes the length but not
257	    /// any existing element).
258	    pub(crate) fn mark_node_dirty(&self, key: &[PathKey]) {
259	        self.notify(key, SubscriptionDepth::Shallow);
260	        self.notify(key, SubscriptionDepth::Deep);
261	        self.mark_ancestors_dirty(key);
262	    }
