264	    /// Notify the deep subscribers on every ancestor of `key`. This does not touch `key` itself.
265	    fn mark_ancestors_dirty(&self, key: &[PathKey]) {
266	        for len in 0..key.len() {
267	            self.notify(&key[..len], SubscriptionDepth::Deep);
268	        }
269	    }
