271	    /// Notify a single set of subscribers (either shallow or deep) at a single path.
272	    fn notify(&self, key: &[PathKey], depth: SubscriptionDepth) {
273	        // We cannot hold the subscribers lock while calling mark_dirty, because mark_dirty can run user code which may cause a new subscriber to be added. If we hold the lock, we will deadlock.
274	        #[allow(clippy::mutable_key_type)]
275	        let mut subscribers = {
276	            let mut write = self.inner.write_unchecked();
277	            let Some(node) = write.root.get_mut(key) else {
278	                return;
279	            };
280	            std::mem::take(depth.subscribers_mut(node))
281	        };
282	        subscribers.retain(|reactive_context| reactive_context.mark_dirty());
283	        // Extend the subscribers list instead of overwriting it in case a subscriber is added while reactive contexts are marked dirty
284	        let mut write = self.inner.write_unchecked();
285	        let Some(node) = write.root.get_mut(key) else {
286	            return;
287	        };
288	        depth.subscribers_mut(node).extend(subscribers);
289	    }
